    17	    await fs.mkdir(conversationsDirectory, { recursive: true });
    18	    const files = await fs.readdir(conversationsDirectory);
    19	    const existingIds = files
    20	      .map((file) => /^([1-9]\d*)\.json$/.exec(file)?.[1])
    21	      .filter((id): id is string => id !== undefined)
    22	      .map(Number);
    23	    const id = existingIds.length === 0 ? 1 : Math.max(...existingIds) + 1;
    24	    const messages: ConversationMessage[] = [];
    25	
    26	    await saveSession(id, messages);
    27	    return { id, messages };
    28	  }
    29	
    30	  async function loadSession(sessionIdText: string): Promise<{ id: number; messages: ConversationMessage[] }> {
    31	    if (!/^[1-9]\d*$/.test(sessionIdText)) {
    32	      throw new Error("세션 ID는 1 이상의 정수여야 합니다.");
    33	    }
    34	
    35	    const id = Number(sessionIdText);
    36	    let parsed: unknown;
    37	    try {
    38	      parsed = JSON.parse(await fs.readFile(sessionPath(id), "utf8"));
    39	    } catch (error) {
    40	      const code = (error as NodeJS.ErrnoException).code;
    41	      if (code === "ENOENT") throw new Error(`${id}번 세션을 찾을 수 없습니다.`);
    42	      throw error;
    43	    }
    44	
    45	    if (!Array.isArray(parsed) || !parsed.every(isConversationMessage)) {
    46	      throw new Error(`${id}.json의 대화 형식이 올바르지 않습니다.`);
    47	    }
    48	    return { id, messages: parsed };
    49	  }
