    51	  function isConversationMessage(value: unknown): value is ConversationMessage {
    52	    if (!value || typeof value !== "object") return false;
    53	    const message = value as Record<string, unknown>;
    54	    return (message.type === "user" || message.type === "assistant") && typeof message.text === "string";
    55	  }
